 function signatureMarkup(ctx,s){return s?`${e(s.id)} · ${e(s.type)} · ${e(s.date)} · ${money(ctx,s.amountCents)} · 账户 ${e(ctx.accountName(s.accountId))}（${e(s.accountId)}）${s.toAccountId?' → '+e(s.toAccountId):''}`:'来源未知';}
 function proofMarkup(ctx,label,p,cutoff){if(!p)return `<p class="spending-warning">${e(label)}不可得，不生成替代或截断依据。</p>`;return `<section class="spending-proof-summary"><h5>${e(label)}</h5><p>原始付款：${signatureMarkup(ctx,p.source)}</p><p>原付款毛额 ${money(ctx,p.grossPaymentCents)} · 现金角色依据 ${e(p.cashProfile.id)} / ${e(p.cashProfile.accountId)}。这是用户声明的账户角色。</p><h5>全部主重复证据（${p.duplicateEvidence.length}）</h5>${p.duplicateEvidence.length?'<ul>'+p.duplicateEvidence.map(x=>`<li>${e(x.id)} · 主 ${signatureMarkup(ctx,x.primarySignature)}<br>影子 ${signatureMarkup(ctx,x.shadowSignature)}</li>`).join('')+'</ul>':empty('无主重复证据。')}<h5>来源层全部退款（${p.refunds.length}）</h5>${p.refunds.length?'<ul>'+p.refunds.map(x=>`<li>${e(x.id)} · 分配 ${money(ctx,x.amountCents)} · ${x.incomeSignature.date>cutoff?'未来已记录退款，未计入截止日实收':'截止日内已记录退款'}<br>退款收入 ${signatureMarkup(ctx,x.incomeSignature)}<br>原付款 ${signatureMarkup(ctx,x.expenseSignature)}</li>`).join('')+'</ul>':empty('无当前退款分配。')}<h5>来源层全部应收（${p.claims.length}）</h5>${p.claims.length?'<ul>'+p.claims.map(x=>`<li>${e(x.id)} · ${money(ctx,x.amountCents)} · 原付款 ${signatureMarkup(ctx,x.expenseSignature)}</li>`).join('')+'</ul>':empty('无当前应收分配。')}<p>退款与应收不减少可归属原付款毛额，也不决定此计划尚需支付的金额。</p>${full(label+'完整字段和全部签名',p)}</section>`;}
 function planMarkup(ctx,pv){if(!pv)return empty('此侧没有当前计划。');const p=pv.plan,last=pv.lastConfirmedRemaining;return `<h4>${e(p.name)} · ${e(p.id)}</h4><p class="spending-stage">${p.stage==='planned'?'计划阶段':'已承诺阶段'} · ${p.status==='cancelled'?'已取消未来贡献':'开放中'} · ${e(PROGRESS[pv.progress])}</p>${metrics(ctx,[['当前估计参考额',p.targetAmountCents],['完整已关联付款毛额',pv.grossPaidCents],['明确确认当前剩余',pv.remainingCents],['已知适用付款部分',pv.knownApplicablePaymentCents],['待复核捕获额',pv.unresolvedCapturedPaymentCents],['估计差异：毛额 + 剩余 − 估计',pv.referenceDifferenceCents],['计划层未来贡献',pv.plannedContributionCents],['承诺层未来贡献',pv.committedContributionCents]])}<p>剩余状态：${e(REMAINING_STATUS[pv.remainingStatus])}。${pv.futureExclusionReason?'取消仅明确排除未来贡献（cancelled-exclusion），不删除实际付款或代替商家接受取消。':''}无剩余只表示用户当前确认，不保证交付、退款或法律义务完结。</p><p>预计日期 ${e(p.expectedDate||'未知')} · ${e(pv.dateStatus)} · 预计账户 ${p.expectedAccountId?e(ctx.accountName(p.expectedAccountId))+'（'+e(p.expectedAccountId)+'）':'未知'} · ${e(pv.expectedAccountStatus)}。缺失账户不替换，实际来源不填写预计字段。</p><p class="spending-user-text">承诺依据：${e(p.commitmentBasis||'未填写')}<br>备注：${e(p.note||'未填写')}<br>创建时间：${e(p.createdAt)}</p><p>当前归属编号：${e(pv.paymentIds.join('、')||'无')}；待复核：${e(pv.unresolvedPaymentIds.join('、')||'无')}。</p>${last?`<p>最后一次明确的非空剩余确认：${money(ctx,last.confirmation.amountCents)} · 截止日 ${e(last.confirmation.reviewedAsOfDate)} · 操作 ${e(last.operationId)} / 修订 ${last.revision}。此历史值不替代当前未知值。</p>${full('原剩余确认及其精确付款集合',last)}`:empty('没有历史非空剩余确认。')}${warningList(pv.warnings)}${full('完整计划字段与派生状态',pv)}`;}
 function usageMarkup(ctx,label,rows){return `<h5>${e(label)}（包括其他计划）</h5>${rows.length?'<ul>'+rows.map(x=>`<li>计划 ${e(x.planId)} · 归属 ${e(x.paymentId)} · ${money(ctx,x.amountCents)}</li>`).join('')+'</ul>':empty('无。')}`;}
 function sourceMarkup(ctx,s,details=false){const t=s.currentSource;return `<article class="spending-source"><h4>来源 ${e(s.transactionId)}</h4><p>${signatureMarkup(ctx,t)}</p><p>账户角色 ${e(s.accountRole)} · 当前依据 ${e(s.basisStatus)} · 截止日 ${e(s.asOfDate)} · ${s.eligibleAtCutoff?'来源类别符合本范围':'此来源当前不能新增关联'}。</p>${metrics(ctx,[['记录原付款毛额（非截止日到账保证）',s.grossPaymentCents],['当前关系重述的个人消费',s.currentPersonalExpenseCents],['全部当前来源退款',s.refundAllCurrentCents],['截止日内已记录退款',s.refundRecordedByCutoffCents],['未来已记录退款',s.refundFutureRecordedCents],['全部当前来源应收',s.claimAllCurrentCents],['当前适用归属毛额',s.applicableAttributedCents],['待复核捕获额',s.unresolvedCapturedCents],['来源毛额剩余归属容量',s.sourceCapacityCents],['本次可新增归属容量',s.allocatableCents]])}<p>个人消费采用全部当前关系重述原购买口径（${e(s.personalExpenseBasis)}），不等于截止日付款或仍欠金额。容量是注释容量，不是可花现金。重复 ${s.componentCounts.duplicates} / 退款 ${s.componentCounts.refunds} / 应收 ${s.componentCounts.claims} 项；未决归属 ${e(s.unresolvedPaymentIds.join('、')||'无')}。</p>${warningList(s.reasonCodes)}${details?proofMarkup(ctx,'当前完整来源依据',s.currentProof,s.asOfDate)+usageMarkup(ctx,'同源所有适用归属',s.applicablePayments)+usageMarkup(ctx,'同源所有待复核捕获',s.unresolvedPayments)+full('全部当前关系组件（未截断）',s.components)+full('完整来源详情',s):button('source','查看完整来源与同源用量',s.transactionId)}${!s.eligibleAtCutoff?`<p>先在原交易、账务核对或账户角色工作区处理事实；不提取押金 / 组合的剩余部分。</p>${button('record-expense','录入真实支出')}${button('account-roles','核对账户角色')}`:''}</article>`;}
 function layersMarkup(ctx,t){return ['planned','committed','grossPaid'].map((key,i)=>`<article><h4>${['计划层：未来剩余','承诺层：未来剩余','实际层：已有付款毛额注释'][i]}</h4>${metrics(ctx,[['完整合计',t[key].completeCents],['已知部分',t[key].knownCents]])}<p>阻挡完整合计的计划：${e(t[key].unresolvedPlanIds.join('、')||'无')}</p></article>`).join('');}
 function eligibilityMarkup(ctx,v){shape(v,eligibility,'eligibility');return `<section class="spending-eligibility"><h4>本次资格：${v.eligible?'当前符合条件':'当前不可执行'}</h4>${metrics(ctx,[['来源剩余归属容量',v.sourceCapacityCents],['最多新增归属',v.maxAdditionalCents],['重核固定旧额',v.amountToReconfirmCents],['当前估计参考额',v.targetAmountCents]])}<p>估计不是归属上限。重核保持原归属毛额，不自动缩额或修复其他待复核条目。</p>${warningList(v.reasonCodes)}${full('完整本次资格和查询',v)}</section>`;}
 function pagination(kind,offset,count){return `<div class="spending-pager">${button(kind+'-prev','上一页','',offset===0?' disabled':'')}<span role="status">${count?`${Math.min(offset+1,count)}–${Math.min(offset+PAGE_SIZE,count)} / ${count}`:'0 条'}</span>${button(kind+'-next','下一页','',offset+PAGE_SIZE>=count?' disabled':'')}</div>`;}
 function render(ctx){try{const cutoff=day(ctx),state=stateOf(ctx),view=engine(ctx).view(state,{asOfDate:cutoff}),catalog=engine(ctx).sources(state,{asOfDate:cutoff,offset:sourceOffset,limit:PAGE_SIZE,accountId:accountFilter||null});const plans=view.plans.filter(v=>`${v.plan.id} ${v.plan.name} ${v.plan.note} ${v.plan.commitmentBasis}`.toLocaleLowerCase().includes(query.toLocaleLowerCase()));planOffset=Math.min(planOffset,Math.max(0,Math.floor((plans.length-1)/PAGE_SIZE)*PAGE_SIZE));const currentIds=new Set(view.plans.map(v=>v.plan.id)),retired=(state.spendingPlanning?.audit||[]).filter(x=>x.action==='retire-plan').flatMap(x=>x.changes.filter(c=>c.kind==='plan'&&!currentIds.has(c.recordId)).map(c=>c.before));return `<section class="spending-workspace" id="spending-root"><article class="card"><div class="card-head"><div><h2>支出计划与承诺</h2><p>计划、承诺、已有付款三层单独核对</p></div>${button('new','登记支出计划')}</div>${caveat()}${knowledge()}<label class="field">日终经济截止日<input id="spending-as-of" type="date" min="0001-01-01" max="9999-12-31" value="${e(cutoff)}" required></label><div class="spending-metrics">${layersMarkup(ctx,view.totals)}</div><p>不把三层相加成总支出、可花现金或现金预测。消费沙盘的一次性计划独立存在，可能描述同一打算；本页不自动匹配、转换或加入沙盘合计。</p>${warningList(view.warnings)}</article><article class="card"><h3>当前计划</h3><label class="field">筛选计划<input id="spending-query" type="search" value="${e(query)}"></label>${plans.slice(planOffset,planOffset+PAGE_SIZE).map(v=>`<article class="spending-plan">${planMarkup(ctx,v)}${button('detail','详情与操作',v.plan.id)}</article>`).join('')||empty('没有符合筛选条件的当前计划。')}${pagination('plans',planOffset,plans.length)}<details class="spending-history"><summary>退役历史（${retired.length}）</summary>${retired.map(p=>`<p>${e(p.name)} · ${e(p.id)} ${button('detail','查看保留历史',p.id)}</p>`).join('')||empty('没有退役记录。')}</details></article><article class="card"><h3>全部记录的来源资格</h3><p>包含不可关联、未来和当前付款所引用的缺失来源；不把不可用来源静默隐藏。</p><label class="field">来源账户<select id="spending-account"><option value="">全部账户（含缺失来源）</option>${state.accounts.map(a=>`<option value="${e(a.id)}"${a.id===accountFilter?' selected':''}>${e(a.name)}</option>`).join('')}</select></label>${catalog.rows.map(s=>sourceMarkup(ctx,s)).join('')||empty('本页没有来源。')}${pagination('sources',sourceOffset,catalog.totalCount)}${button('record-expense','录入真实支出')}${button('account-roles','核对账户角色')}</article></section>`;}catch(error){return `<section class="card"><h2>支出计划暂不可用</h2><p role="alert">${e(error.message)}</p><p>账本未改动。请核对截止日与模块。</p></section>`;}}
 function paymentMarkup(ctx,pv,p){return `<article class="spending-receipt"><h4>付款归属 ${e(p.id)}</h4><p>${money(ctx,p.amountCents)} · 来源 ${e(p.transactionId)} · 原经济日 ${e(pv.capturedEconomicDate)} · 复核截止日 ${e(p.reviewedAsOfDate)} · 创建 ${e(p.createdAt)}</p><p>当前适用性：${e(APPLICABILITY[pv.applicability])} · 参考 ${e(p.reference||'未填写')}</p>${warningList(pv.reasonCodes)}${proofMarkup(ctx,'原不可变捕获依据',p.proof,day(ctx))}${button('reverse','撤销此付款归属',p.id)}${button('reconfirm','重新核对此付款',p.id,pv.applicability==='applicable'?' disabled':'')}${button('source','查看当前来源与全部用量',p.transactionId)}</article>`;}
 function planDetails(ctx,id){try{const state=stateOf(ctx),view=engine(ctx).view(state,{asOfDate:day(ctx)}),pv=view.plans.find(v=>v.plan.id===id),events=(state.spendingPlanning?.audit||[]).filter(x=>x.changes.some(c=>c.kind==='plan'&&c.recordId===id)),record=pv?.plan||events.at(-1)?.changes.find(c=>c.kind==='plan')?.before;if(!record)throw Error('计划与保留历史不存在。');const rows=view.payments.filter(x=>x.planId===id),records=new Map((state.spendingPlanning?.payments||[]).map(x=>[x.id,x]));const controls=pv?`<div class="spending-actions">${button('edit','修改计划资料',id)}${record.status==='open'?button('cancel','取消未来计划',id)+button('remaining','明确确认当前剩余',id):button('reopen','重开计划',id)}${record.stage==='planned'&&record.status==='open'?button('commit','确认承诺',id):''}${record.status==='cancelled'?button('return','返回计划阶段',id,rows.length?' disabled':'')+button('retire','退役计划',id,rows.length?' disabled':''):''}${button('allocate','关联已有付款',id,record.status!=='open'||record.stage!=='committed'||pv.unresolvedPaymentIds.length?' disabled':'')}</div>`:'';dialog(ctx,pv?'支出计划详情与修复':'退役计划的保留历史',`<div class="spending-details">${caveat()}${knowledge()}${pv?planMarkup(ctx,pv):`<h3>${e(record.name)} · 已退役</h3>${full('最后保留的计划',record,true)}`}${controls}<p>先逐项撤销所有当前归属，再取消并退役或返回计划阶段。撤销归属保留真实付款和历史，剩余不会按算术自动重开。</p><h3>当前逐项付款</h3>${rows.map(x=>paymentMarkup(ctx,x,records.get(x.paymentId))).join('')||empty('没有当前付款归属。')}<h3>完整历史（包括原估计、已撤销、重核和退役）</h3>${events.map(x=>`<article><p>修订 ${x.revision} · ${e(ACTIONS[x.action])} · ${e(x.at)} · 截止日 ${e(x.asOfDate)}<br>原因：${e(x.reason)} · 操作 ${e(x.id)}</p>${full('完整原子操作与 before / after',x)}</article>`).join('')}</div>`,'<button class="btn" type="button" data-close>关闭</button>');}catch(error){ctx.error(error.message);}}
 function showSource(ctx,id){try{const s=engine(ctx).source(stateOf(ctx),{asOfDate:day(ctx),transactionId:id});dialog(ctx,'完整付款来源与同源用量',`<div class="spending-details">${knowledge()}${sourceMarkup(ctx,s,true)}</div>`,'<button class="btn" type="button" data-close>关闭</button>');}catch(error){ctx.error(error.message);}}
 function needsRemaining(action){return !['update-plan','cancel-plan','retire-plan'].includes(action);}
 function draft(ctx,action,id){const d={action,id,asOfDate:day(ctx),reason:'',remaining:'',remainingUnknown:false};if(action==='create-plan')return {...d,name:'',amount:'',expectedDate:'',expectedAccountId:'',note:''};if(action==='update-plan'){const p=stateOf(ctx).spendingPlanning?.plans.find(p=>p.id===id);if(!p)throw Error('计划已不存在。');return {...d,name:p.name,amount:p.targetAmountCents===null?'':ctx.amountText(p.targetAmountCents),expectedDate:p.expectedDate||'',expectedAccountId:p.expectedAccountId||'',note:p.note};}if(action==='commit-plan')return {...d,commitmentBasis:''};if(action==='allocate-payment')return {...d,transactionId:'',amount:'',reference:'',sourceOffset:0,sourceAccount:''};return d;}
 function planFields(ctx,d){const state=stateOf(ctx),missing=d.expectedAccountId&&!state.accounts.some(a=>a.id===d.expectedAccountId);return `<div class="form-grid">${field('计划名称','name',d.name,'maxlength="80" required')}${field('当前估计参考额（人民币元；留空为未知）','amount',d.amount,'inputmode="decimal" maxlength="14"')}${dateField('expectedDate','预计日期（留空为未知）',d.expectedDate,false)}<label class="field">预计账户（留空为未知）<select name="expectedAccountId"><option value="">未知 / 未填写</option>${missing?`<option value="${e(d.expectedAccountId)}" selected>缺失账户 ${e(d.expectedAccountId)}（保留原引用）</option>`:''}${state.accounts.map(a=>`<option value="${e(a.id)}"${a.id===d.expectedAccountId?' selected':''}>${e(a.name)}</option>`).join('')}</select></label>${area('计划备注','note',d.note)}</div><p>估计只作参考，不限制付款归属，不表示欠款。修改当前估计有审计，最初估计保留在历史；预计日期与账户不会由付款自动填入。</p>`;}
 function remainingFields(d){return `<section class="spending-remaining"><h3>单独确认本次操作后的当前剩余</h3>${field('当前仍计划 / 承诺的剩余金额（人民币元；可为 0）','remaining',d.remaining,'inputmode="decimal" maxlength="14"')}<label class="confirm-check"><input type="checkbox" name="remainingUnknown"${d.remainingUnknown?' checked':''}>我明确选择：当前剩余未知</label><p>空白不是 0。须明确填写金额或选择未知。退款、撤销归属、重核与重开不会自动形成新欠款；即使建议简单相减，也须你单独确认。其他付款仍待复核时，只能选择未知。</p></section>`;}
 function sourcePicker(ctx,d){const catalog=engine(ctx).sources(stateOf(ctx),{asOfDate:d.asOfDate,offset:d.sourceOffset,limit:PAGE_SIZE,accountId:d.sourceAccount||null});return `<section><h3>选择已有付款来源</h3><label class="field">来源账户筛选<select name="sourceAccount"><option value="">全部账户（含缺失来源）</option>${stateOf(ctx).accounts.map(a=>`<option value="${e(a.id)}"${a.id===d.sourceAccount?' selected':''}>${e(a.name)}</option>`).join('')}</select></label><label class="field full">已有记录（不可用来源保留并禁用）<select name="transactionId" required><option value="">请核对来源后明确选择</option>${catalog.rows.map(s=>`<option value="${e(s.transactionId)}"${s.transactionId===d.transactionId?' selected':''}${!s.eligibleAtCutoff||s.allocatableCents===null||s.allocatableCents===0?' disabled':''}>${e(s.transactionId)} · ${e(s.currentSource?.date||'缺失')} · ${e(s.currentSource?.type||'missing')} · 毛额 ${money(ctx,s.grossPaymentCents)} · ${e(s.reasonCodes.join('、')||(!s.allocatableCents?'无可新增容量':'来源类别可用'))}</option>`).join('')}</select></label><div class="spending-pager"><button type="button" class="btn" id="spending-picker-prev"${d.sourceOffset===0?' disabled':''}>上一页来源</button><span>${catalog.totalCount?`${Math.min(d.sourceOffset+1,catalog.totalCount)}–${Math.min(d.sourceOffset+PAGE_SIZE,catalog.totalCount)} / ${catalog.totalCount}`:'0 条'}</span><button type="button" class="btn" id="spending-picker-next"${catalog.nextOffset===null?' disabled':''}>下一页来源</button></div><ul>${catalog.rows.filter(s=>!s.eligibleAtCutoff||s.allocatableCents===null||s.allocatableCents===0).map(s=>`<li>${e(s.transactionId)}：${e(s.reasonCodes.map(x=>REASONS[x]+'（'+x+'）').join('；')||'同源存在待复核归属或没有可新增容量')}。${button('source','完整原因',s.transactionId)}</li>`).join('')}</ul><p>分页或账户筛选会取消旧选择。先处理实际事实，不从不支持的押金或购买组合中提取部分。估计额不是来源上限。</p>${button('record-expense','录入真实支出')}${button('account-roles','核对账户角色')}<div id="spending-picked-source" aria-live="polite"></div></section>`;}
 function readDraft(form,d){for(const key of Object.keys(d)){const n=form.elements.namedItem(key);if(n)d[key]=key==='remainingUnknown'?n.checked===true:n.value;}}
 function remaining(ctx,d){if(d.remainingUnknown)return null;if(typeof d.remaining!=='string'||!d.remaining.trim())throw Error('请明确填写当前剩余（可为 0），或勾选「当前剩余未知」。');return ctx.ledger.parseAmount(d.remaining,{allowZero:true});}
 function command(ctx,d){const action=d.action;if(action==='create-plan'||action==='update-plan'){const p={name:d.name,targetAmountCents:d.amount.trim()===''?null:ctx.ledger.parseAmount(d.amount),expectedDate:d.expectedDate||null,expectedAccountId:d.expectedAccountId||null,note:d.note};return action==='create-plan'?{action,plan:p,remainingAfterCents:remaining(ctx,d)}:{action,planId:d.id,patch:p};}if(['cancel-plan','retire-plan'].includes(action))return {action,planId:d.id};if(action==='commit-plan')return {action,planId:d.id,commitmentBasis:d.commitmentBasis,remainingAfterCents:remaining(ctx,d)};if(action==='allocate-payment')return {action,planId:d.id,transactionId:d.transactionId,amountCents:ctx.ledger.parseAmount(d.amount),reference:d.reference,remainingAfterCents:remaining(ctx,d)};if(['reverse-payment','reconfirm-payment'].includes(action))return {action,paymentId:d.id,remainingAfterCents:remaining(ctx,d)};return {action,planId:d.id,remainingAfterCents:remaining(ctx,d)};}
 function showDraft(ctx,d){try{let body=dateField('asOfDate','明确日终经济截止日',d.asOfDate);if(['create-plan','update-plan'].includes(d.action))body+=planFields(ctx,d);else if(d.action==='commit-plan')body+=area('承诺依据（必填，保留审计）','commitmentBasis',d.commitmentBasis,true)+'<p>承诺替换计划层贡献，同一笔未来剩余不同时计入两层。</p>';else if(d.action==='allocate-payment')body+=sourcePicker(ctx,d)+field('本次归属原付款毛额（人民币元）','amount',d.amount,'inputmode="decimal" maxlength="14" required')+area('付款归属参考','reference',d.reference);else if(['reverse-payment','reconfirm-payment'].includes(d.action)){const p=stateOf(ctx).spendingPlanning?.payments.find(p=>p.id===d.id);if(!p)throw Error('付款归属已不存在。');body+=`<p>归属 ${e(p.id)} · 固定毛额 ${money(ctx,p.amountCents)} · 原来源 ${e(p.transactionId)} · 参考 ${e(p.reference||'无')}</p>`+proofMarkup(ctx,'原付款捕获依据',p.proof,d.asOfDate)+(d.action==='reverse-payment'?'<p>只撤销此归属，真实付款仍保留。剩余须明确选择，不按退款净额或撤销毛额自动重开。</p>':'<p>原归属撤销并以新编号重新捕获当前完整依据；毛额、计划、来源和参考不变。其他未决条目不会自动修复。</p><div id="spending-picked-source" aria-live="polite"></div>');}else body+=`<p>${{'cancel-plan':'取消只排除未来计划或承诺贡献，保留付款、最后确认及完整历史；不代表商家接受取消或退款。','reopen-plan':'重开恢复原阶段，必须重新明确当前剩余或未知。','return-to-plan':'只有已取消且没有当前付款的计划可返回计划阶段；清除当前承诺依据，历史保留。','retire-plan':'只有已取消且没有当前付款的计划可退役。编号、原估计、全部操作历史永久保留。','confirm-remaining':'单独确认当前剩余；不修改目标参考或实际付款。'}[d.action]}</p>`;if(needsRemaining(d.action))body+=remainingFields(d);dialog(ctx,ACTIONS[d.action],`<form id="entry-form" class="spending-form">${caveat()}${body}${area('本次确认原因（确认保存前必填）','reason',d.reason)}${errorBox()}<div class="modal-bottom">${cancelButton(ctx)}<button class="btn primary" id="spending-preview" type="submit">生成完整影响预览，不保存</button></div></form>`,'',token=>{const form=bindForm(ctx,token,f=>{readDraft(f,d);if(!ctx.ledger.validDate(d.asOfDate))throw Error('请填写有效的日终经济截止日。');showReview(ctx,command(ctx,d),{asOfDate:d.asOfDate},d);});const unknown=form.elements.namedItem('remainingUnknown'),amount=form.elements.namedItem('remaining');if(unknown){const update=()=>{if(current(ctx,token,form)){amount.disabled=unknown.checked===true;amount.required=!unknown.checked;}};unknown.onchange=update;update();}if(d.action==='allocate-payment'){const redraw=()=>{if(!current(ctx,token,form))return;readDraft(form,d);d.transactionId='';showDraft(ctx,d);};ctx.$('#spending-picker-prev').onclick=()=>{d.sourceOffset=Math.max(0,d.sourceOffset-PAGE_SIZE);redraw();};ctx.$('#spending-picker-next').onclick=()=>{d.sourceOffset+=PAGE_SIZE;redraw();};form.elements.namedItem('sourceAccount').onchange=()=>{d.sourceOffset=0;redraw();};}
 if(['allocate-payment','reconfirm-payment'].includes(d.action)){const picker=form.elements.namedItem('transactionId'),cutoff=form.elements.namedItem('asOfDate');const draw=()=>{if(!current(ctx,token,form))return;const box=ctx.$('#spending-picked-source'),submit=ctx.$('#spending-preview');try{if(picker&&!picker.value){box.innerHTML=empty('请选择并核对原付款来源。');submit.disabled=true;return;}const query=d.action==='allocate-payment'?{action:d.action,planId:d.id,transactionId:picker.value,asOfDate:cutoff.value}:{action:d.action,paymentId:d.id,asOfDate:cutoff.value};const eligibility=engine(ctx).eligibility(stateOf(ctx),query),sourceId=picker?.value||stateOf(ctx).spendingPlanning.payments.find(p=>p.id===d.id)?.transactionId,source=engine(ctx).source(stateOf(ctx),{asOfDate:cutoff.value,transactionId:sourceId});box.innerHTML=sourceMarkup(ctx,source,true)+eligibilityMarkup(ctx,eligibility);submit.disabled=!eligibility.eligible;}catch(error){box.innerHTML=`<p class="spending-warning" role="alert">${e(error.message)}</p>`;submit.disabled=true;}};if(picker)picker.onchange=draw;cutoff.onchange=()=>{if(d.action==='allocate-payment'){readDraft(form,d);d.sourceOffset=0;d.transactionId='';showDraft(ctx,d);}else draw();};draw();}
 });}catch(error){ctx.error(error.message);}}
 function matchMarkup(label,m){return `<p>${e(label)}：${m?'日期 '+e(MATCH[m.date])+' · 账户 '+e(MATCH[m.account]):'此侧无计划 / 付款，不作比较'}</p>`;}
 function reviewMarkup(ctx,raw){const r=JSON.parse(root.MoneygoSpendingCore.canonicalData(raw,{maxBytes:8388608}));requireReview(r);const rd=r.remainingDecision;return `<h3>${e(ACTIONS[r.command.action])}</h3><p>固定日终截止日 ${e(r.options.asOfDate)} · 待确认预览时间 ${e(r.confirmationStamp.previewAt)}。新建记录最终保存时记录确认时间与本次原因；不改变经济截止日、金额、归属和依据。</p>${knowledge()}<section><h3>目标计划完整前后</h3><p>计划 ${e(r.plan.planId)}</p><div class="spending-compare"><section><h4>操作前</h4>${planMarkup(ctx,r.plan.before)}</section><section><h4>操作后</h4>${planMarkup(ctx,r.plan.after)}</section></div></section><section class="spending-remaining"><h3>单独确认的当前剩余决定</h3>${metrics(ctx,[['操作前完整剩余',rd.before],['操作后完整剩余',rd.after],['本次明确提交',rd.submitted],['仅供核对的简单相减建议',rd.suggestedCents]])}<p>${rd.submissionRequired?'本操作必须明确提交金额或未知。':'本操作保留原确认，不重新填写剩余。'}建议状态：${e({'simple-subtraction':'简单相减建议，仍须单独确认','not-applicable':'本次不适用','refund-or-claim-context':'有退款或应收，不提供相减建议','unknown-previous-remaining':'原剩余未知，不提供建议','negative-result':'简单相减为负，不提供建议','explicit-review-required':'须明确独立复核'}[rd.suggestionStatus])}。</p>${rd.suggestionStatus==='simple-subtraction'&&rd.submitted!==rd.suggestedCents?'<p class="spending-warning">你提交的剩余与简单相减建议不同。请在本次原因中说明；系统不会截断或改成目标余量。</p>':''}${rd.submissionRequired&&rd.submitted===null?'<p class="spending-warning">本次明确选择未知，未把空白当作 0。</p>':''}${rd.submissionRequired&&rd.submitted===0?'<p>本次明确确认剩余为 0；这不表示商家已交付、已退款或已解除法律义务。</p>':''}${full('完整剩余决定',rd)}</section><section><h3>当前估计与差异</h3>${metrics(ctx,[['操作前估计',r.targetComparison.beforeTargetCents],['操作后估计',r.targetComparison.afterTargetCents],['操作前毛额 + 剩余 − 估计',r.targetComparison.beforeDifferenceCents],['操作后毛额 + 剩余 − 估计',r.targetComparison.afterDifferenceCents]])}<p>原估计保留在创建历史，当前估计可显式修改。差异不表示新增真实支出或现金需求。</p></section><section><h3>每项付款：捕获、适用性和预计字段差异</h3>${r.payments.map(x=>`<article class="spending-review-receipt"><h4>${e(x.payment.id)} · ${money(ctx,x.payment.amountCents)}</h4><p>计划 ${e(x.payment.planId)} · 来源 ${e(x.payment.transactionId)} · ${x.before===null?'本次新增捕获':x.after===null?'本次撤销，历史保留':'归属保留'}<br>创建 ${e(x.payment.createdAt)} · 原复核截止日 ${e(x.payment.reviewedAsOfDate)} · 参考 ${e(x.payment.reference||'无')}</p><p>捕获与当前 proof 比较：${e(x.proofComparison.result)} · 差异字段 ${e(x.proofComparison.differentFields.join('、')||'无 / 不可比较')}。</p>${proofMarkup(ctx,'不可变付款捕获依据',x.payment.proof,r.options.asOfDate)}<div class="spending-compare"><section><h5>操作前</h5>${x.before?`<p>${e(APPLICABILITY[x.before.applicability])} · 捕获经济日 ${e(x.before.capturedEconomicDate)} · ${money(ctx,x.before.capturedAmountCents)}</p>${warningList(x.before.reasonCodes)}`:empty('此前没有这项归属。')}${matchMarkup('捕获对预计',x.capturedMatchBefore)}${matchMarkup('当前来源对预计',x.currentMatchBefore)}${full('完整前侧付款适用性',x.before)}</section><section><h5>操作后</h5>${x.after?`<p>${e(APPLICABILITY[x.after.applicability])} · 捕获经济日 ${e(x.after.capturedEconomicDate)} · ${money(ctx,x.after.capturedAmountCents)}</p>${warningList(x.after.reasonCodes)}`:empty('不再活跃，真实付款与审计保留。')}${matchMarkup('捕获对预计',x.capturedMatchAfter)}${matchMarkup('当前来源对预计',x.currentMatchAfter)}${full('完整后侧付款适用性',x.after)}</section></div>${full('完整不可变付款和全部比较',x)}</article>`).join('')||empty('此计划前后没有当前付款归属。')}</section><section><h3>完整来源与所有计划的同源使用</h3><p>来源退款和应收单独展示，不给共享来源的计划虚构退款份额。</p>${r.sources.map(x=>`<article class="spending-review-source"><h4>来源 ${e(x.transactionId)}</h4><div class="spending-compare"><section><h5>操作前：完整依据与全部用量</h5>${sourceMarkup(ctx,x.before,true)}</section><section><h5>操作后：完整依据与全部用量</h5>${sourceMarkup(ctx,x.after,true)}</section></div></article>`).join('')||empty('此操作没有受影响付款来源。')}</section>${r.operationEligibility?eligibilityMarkup(ctx,r.operationEligibility):empty('此操作不需要新增或重核付款资格计算。')}<section><h3>三个独立层的完整前后影响</h3><p>三层不相加，也不加入现有消费沙盘或历史财务合计。未知不按 0 计算。</p><div class="spending-compare"><section><h4>操作前</h4>${layersMarkup(ctx,r.layerImpacts.before)}</section><section><h4>操作后</h4>${layersMarkup(ctx,r.layerImpacts.after)}</section></div></section><section><h3>全部真实财务分量：逐项零变化</h3><p>全部已记录日期的当前财务模型，不表示截止日可信现金。</p>${metrics(ctx,[['普通收入变化',r.financialDeltas.ordinaryIncomeCents],['个人消费变化',r.financialDeltas.personalExpenseCents],['实际流入变化',r.financialDeltas.cashInCents],['实际流出变化',r.financialDeltas.cashOutCents]])}${r.financialDeltas.accounts.map(a=>`<article><h4>${e(ctx.accountName(a.accountId))} · ${e(a.accountId)}</h4>${metrics(ctx,[['流入变化',a.inflowCents],['流出变化',a.outflowCents],['余额变化',a.balanceCents]])}</article>`).join('')}<p>除外层版本与 spendingPlanning 外，所有持久子树经规范化比较相同；包括原始交易、实际关系、历史月结、收入计划、消费沙盘。</p>${full('逐项 FinancialDeltas',r.financialDeltas)}${full('全部其他子树不变证明',r.unchangedSubtrees)}</section><section><h3>完整原子审计操作</h3><p>操作 ${e(r.operation.id)} · 修订 ${r.operation.revision} · ${e(ACTIONS[r.operation.action])} · 截止日 ${e(r.operation.asOfDate)} · 原因待确认。</p><ul>${r.operation.changes.map(c=>`<li>${c.kind==='plan'?'计划':'付款'} ${e(c.recordId)}：${c.before===null?'新建':c.after===null?'移出当前，保留历史':'更新'}${c.reverses?'；反向引用原创建操作 '+e(c.reverses):''}</li>`).join('')}</ul>${full('精确 before / after、所有新旧编号与剩余快照',r.operation,true)}</section>${full('完整不可变复核 payload',r)}`;}
 function showReview(ctx,cmd,o,d){dialog(ctx,'逐项核对支出计划影响，再确认保存',`<form id="entry-form" class="spending-form spending-review">${caveat()}<div id="spending-review-body" aria-live="polite">正在生成完整复核内容。</div>${area('本次确认原因（必填；剩余与建议不同请说明）','reason',d.reason,true)}<label class="confirm-check"><input type="checkbox" name="confirmed" required aria-describedby="spending-form-error">我已核对完整前后计划、原付款毛额、全部当前与捕获依据、同源其他计划用量、预计日期账户差异、明确剩余决定、三层影响及所有真实财务分量零变化，确认仅保存本次注释</label>${errorBox()}<p id="spending-review-status" class="spending-warning" role="status"></p><div class="modal-bottom">${cancelButton(ctx)}<button class="btn" type="button" id="spending-back">返回修改</button><button class="btn" type="button" id="spending-fresh" hidden>重新生成预览并核对</button><button class="btn primary" type="submit" id="spending-commit" disabled>确认保存本次注释</button></div></form>`,'',token=>{let c;const form=bindForm(ctx,token,f=>{if(!token.ticket)throw Error('此预览已失效，请重新生成并核对。');if(f.elements.namedItem('confirmed')?.checked!==true)throw Error('请明确勾选已核对完整预览。');const why=reason(read(f,'reason'));d.reason=why;const ticket=token.ticket;token.ticket=null;token.submitted=true;ctx.$('#spending-commit').disabled=true;let saved=false;try{saved=ctx.change(()=>{if(!current(ctx,token,form))throw Error('窗口已失效，请重新预览。');return c.commit(stateOf(ctx),ticket,{confirmed:true,reason:why});},'已保存支出计划注释；真实付款与现金记录不变');}catch(error){fail(ctx,error);}if(saved===true){invalidate();return;}c.cancel(ticket);if(current(ctx,token,form)){f.elements.namedItem('confirmed').checked=false;ctx.$('#spending-fresh').hidden=false;ctx.$('#spending-review-status').textContent='本次未保存，原账本不变。旧预览已作废；请重新生成、核对并再次明确确认。';form.dataset.dirty='true';}});form.dataset.dirty='true';ctx.$('#spending-back').onclick=()=>{if(!current(ctx,token,form))return;d.reason=read(form,'reason');showDraft(ctx,d);};ctx.$('#spending-fresh').onclick=()=>{if(!current(ctx,token,form))return;d.reason=read(form,'reason');showReview(ctx,cmd,o,d);};try{c=getCoordinator(ctx);const ticket=c.preview(stateOf(ctx),cmd,o);token.ticket=ticket;const markup=reviewMarkup(ctx,ownValue(ticket,'review'));ctx.$('#spending-review-body').innerHTML=markup;ctx.$('#spending-commit').disabled=false;}catch(error){if(token.ticket&&c)c.cancel(token.ticket);token.ticket=null;ctx.$('#spending-review-body').innerHTML='<p class="spending-warning">没有可提交的完整预览；账本未保存。</p>';ctx.$('#spending-fresh').hidden=false;fail(ctx,error);}});}
 function dispose(){invalidate();if(boundDocument&&clickListener)boundDocument.removeEventListener?.('click',clickListener);if(boundDocument&&closeListener){boundDocument.removeEventListener?.('click',closeListener,true);boundDocument.removeEventListener?.('keydown',closeListener,true);}context=null;coordinator=null;engineOwner=null;boundDocument=null;clickListener=null;closeListener=null;lifecycle=null;asOfDate='';query='';accountFilter='';planOffset=0;sourceOffset=0;}
 function initialize(ctx){if(!active(ctx))return;context=ctx;if(lifecycle!==ctx.onDispose){lifecycle=ctx.onDispose;ctx.onDispose?.(dispose);}if(boundDocument===root.document)return;boundDocument=root.document;if(!boundDocument)return;closeListener=event=>{if(event.type==='keydown'&&event.key!=='Escape')return;if(event.type==='click'&&!event.target.closest?.('[data-close]'))return;const token=activeDialog,owner=context;Promise.resolve().then(()=>{if(token&&activeDialog===token&&owner&&(!token.form||owner.$('#entry-form')!==token.form))invalidate();});};clickListener=event=>{const node=event.target.closest?.('[data-spending-action]'),ctx=context;if(!node||node.disabled||!ctx||!active(ctx)||node.isConnected===false)return;const action=node.dataset.spendingAction,id=node.dataset.spendingId;if(typeof action!=='string')return;if(!activeDialog&&ctx.getPage&&ctx.getPage()!==(ctx.pageId||'spending-planning'))return;try{if(action==='detail'){planDetails(ctx,id);return;}if(action==='source'){showSource(ctx,id);return;}if(action==='record-expense'){if(typeof ctx.recordExpense!=='function')throw Error('请从「记一笔」录入真实支出。');invalidate();ctx.recordExpense();return;}if(action==='account-roles'){if(typeof ctx.editAccountRoles!=='function')throw Error('请从「信用义务」核对账户角色。');invalidate();ctx.editAccountRoles();return;}if(['plans-prev','plans-next','sources-prev','sources-next'].includes(action)){invalidate();const n=action.endsWith('next')?PAGE_SIZE:-PAGE_SIZE;if(action.startsWith('plans'))planOffset=Math.max(0,planOffset+n);else sourceOffset=Math.max(0,sourceOffset+n);ctx.render();return;}const mapped={new:'create-plan',edit:'update-plan',commit:'commit-plan',cancel:'cancel-plan',reopen:'reopen-plan',return:'return-to-plan',remaining:'confirm-remaining',retire:'retire-plan',allocate:'allocate-payment',reverse:'reverse-payment',reconfirm:'reconfirm-payment'}[action];if(mapped)showDraft(ctx,draft(ctx,mapped,id));}catch(error){ctx.error(error.message);}};boundDocument.addEventListener('click',clickListener);boundDocument.addEventListener('click',closeListener,true);boundDocument.addEventListener('keydown',closeListener,true);}
 function bind(ctx){initialize(ctx);if(!active(ctx))return;const cutoff=ctx.$('#spending-as-of'),search=ctx.$('#spending-query'),account=ctx.$('#spending-account');if(cutoff)cutoff.onchange=()=>{if(!active(ctx))return;try{if(!ctx.ledger.validDate(cutoff.value))throw Error('请填写有效截止日。');asOfDate=cutoff.value;planOffset=0;sourceOffset=0;invalidate();ctx.render();}catch(error){ctx.error(error.message);}};if(search)search.oninput=()=>{if(!active(ctx))return;query=search.value;planOffset=0;invalidate();ctx.render();};if(account)account.onchange=()=>{if(!active(ctx))return;accountFilter=account.value;sourceOffset=0;invalidate();ctx.render();};}
 return Object.freeze({render,bind,initialize,invalidate,planDetails});
